  'function bArom(ex){var z=zh();document.getElementById(\'aromg\').innerHTML=ex.arom.map(function(a){return \'<div class=\\\'ai\\\'><div class=\\\'aj\\\'>\'+(z?a.jz:a.je)+\'</div><div class=\\\'ar\\\'>\'+a.r+\'</div><div class=\\\'as\\\'>\'+(z?a.sz:a.se)+\'</div></div>\';}).join(\'\');}',
  'function bFasc(ex){var z=zh();document.getElementById(\'fasc\').innerHTML=ex.fascia.map(function(f){return \'<div class=\\\'fi\\\'><span class=\\\'fd\\\' style=\\\'background:\'+f.c+\';box-shadow:0 0 4px \'+f.c+\'\\\'></span><div><div class=\\\'fn\\\'>\'+(z?f.nz:f.ne)+\'</div><div class=\\\'fm\\\'>\'+(z?f.mz:f.me)+\'</div></div></div>\';}).join(\'\');}',
  'function bTP(ex){var z=zh();document.getElementById(\'tplist\').innerHTML=ex.tp.map(function(t){return \'<div class=\\\'tpi\\\'><span class=\\\'tpd\\\'></span><div><span class=\\\'tpl\\\'>\'+(z?t.lz:t.le)+\'</span><div class=\\\'tpt\\\'>\'+(z?t.tz:t.te)+\'</div></div></div>\';}).join(\'\');}',
  'function bRepair(ex){var z=zh();var r=ex.repair[cPh];document.getElementById(\'rc\').textContent=r.e;document.getElementById(\'rcz\').textContent=r.z;document.getElementById(\'rcz\').style.display=z?\'block\':\'none\';document.querySelectorAll(\'.rtab\').forEach(function(b){b.classList.toggle(\'on\',b.dataset.ph===cPh);});}',
  'function loadEx(k){cEx=k;',
  '  var fasciaOn=document.querySelector(\'.layerbtn[data-ly=\\\'fascia\\\']\');',
  '  if(fasciaOn&&fasciaOn.classList.contains(\'on\')) updateFasciaOverlay(k);var ex=EX[k];if(!ex)return;document.getElementById(\'atitle\').textContent=ex.ten;document.getElementById(\'atitlezh\').textContent=ex.tzh;document.querySelectorAll(\'.xbtn\').forEach(function(b){b.classList.toggle(\'on\',b.dataset.ex===k);});document.querySelectorAll(\'.dot\').forEach(function(d){d.classList.toggle(\'on\',d.dataset.key===k);});bBars(ex);bRels(ex);bArom(ex);bFasc(ex);bTP(ex);bRepair(ex);renderSVG();}',
  'document.querySelectorAll(\'[data-gd]\').forEach(function(b){b.addEventListener(\'click\',function(){cGd=this.dataset.gd;document.querySelectorAll(\'[data-gd]\').forEach(function(x){x.classList.toggle(\'on\',x.dataset.gd===cGd);});renderSVG();});});',
