  '};',
  '',
  'function updateFasciaOverlay(exKey){',
  '  var active=FASCIA_MAP[exKey]||[];',
  '  [\'fo-sbl\',\'fo-sfl\',\'fo-ll\',\'fo-fal\',\'fo-fl\'].forEach(function(id){',
  '    var el=document.getElementById(id);',
  '    if(!el) return;',
  '    var show=active.indexOf(id)>=0;',
  '    el.style.display=show?\'\':\'none\';',
  '    if(show) el.classList.add(\'tense\');',
  '    else el.classList.remove(\'tense\');',
  '  });',
  '}',
  'document.getElementById(\'dslider\').addEventListener(\'input\',function(){document.getElementById(\'dval\').textContent=this.value+\'%\';var op=parseInt(this.value)/100;document.querySelectorAll(\'.mp\').forEach(function(p){p.style.opacity=op;});});',
  'document.getElementById(\'mt2\').addEventListener(\'click\',function(){pOpen=!pOpen;document.getElementById(\'rp\').classList.toggle(\'on\',pOpen);this.textContent=pOpen?\'\\u00d7\':\'\\u2630\';});',
  'document.querySelectorAll(\'.pt\').forEach(function(b){b.addEventListener(\'click\',function(){document.querySelectorAll(\'.pt\').forEach(function(x){x.classList.remove(\'on\');});this.classList.add(\'on\');if(!pOpen){pOpen=true;document.getElementById(\'rp\').classList.add(\'on\');document.getElementById(\'mt2\').textContent=\'\\u00d7\';}var t=this.dataset.pt;var el=t===\'analysis\'?document.getElementById(\'atitle\'):t===\'arom\'?document.getElementById(\'aromg\'):t===\'fascia\'?document.getElementById(\'fasc\'):document.getElementById(\'tplist\');if(el)el.scrollIntoView({behavior:\'smooth\',block:\'start\'});});});',
  'function showToast(m){var t=document.getElementById(\'toast\');t.textContent=m;t.classList.add(\'on\');setTimeout(function(){t.classList.remove(\'on\');},2000);}',
  'var tx=0;document.getElementById(\'ca\').addEventListener(\'touchstart\',function(e){tx=e.touches[0].clientX;},{passive:true});document.getElementById(\'ca\').addEventListener(\'touchend\',function(e){var dx=e.changedTouches[0].clientX-tx;var ks=Object.keys(EX);var i=ks.indexOf(cEx);if(dx<-50&&i<ks.length-1)loadEx(ks[i+1]);else if(dx>50&&i>0)loadEx(ks[i-1]);},{passive:true});',
  'function buildDots(){var c=document.getElementById(\'dots\');c.innerHTML=\'\';Object.keys(EX).forEach(function(k){var d=document.createElement(\'div\');d.className=\'dot\';d.dataset.key=k;c.appendChild(d);});}',
