  '  {slug:\'tibialis\',   en:\'Tibialis Anterior\', zh:\'\\u811b\\u524d\\u808c\',   layer:\'Superficial\', col:\'#00ff88\'},',
  '  {slug:\'calves\',     en:\'Gastrocnemius\',     zh:\'\\u8153\\u9b5a\\u808c\',   layer:\'Superficial\', col:\'#ff6b35\'},',
  '  {slug:\'upper-back\', en:\'Latissimus Dorsi\',  zh:\'\\u95ca\\u80cc\\u808c\',   layer:\'Superficial\', col:\'#ff2d4a\'},',
