  '  {slug:\'hamstring\',  en:\'Hamstrings\',        zh:\'\\u817f\\u5f8c\\u808c\\u7fa4\', layer:\'Superficial\', col:\'#ff2d4a\'},',
  '];',
  'var MGROUPS = [',
  '  {en:\'UPPER BODY\',zh:\'\\u4e0a\\u80a2\',slugs:[\'trapezius\',\'deltoids\',\'chest\',\'biceps\',\'triceps\',\'forearm\']},',
  '  {en:\'CORE\',zh:\'\\u6838\\u5fc3\',slugs:[\'abs\',\'obliques\']},',
