  'function selMuscle(slug) {',
  '  curHL = slug;',
  '  // Highlight SVG paths',
  '  document.querySelectorAll(\'.mp\').forEach(function(p){ p.classList.remove(\'highlighted\'); });',
  '  var targets = document.querySelectorAll(\'.mp[data-slug="\' + slug + \'"]\');',
  '  if (targets.length === 0) {',
  '    showToast(zh() ? \'\\u8acb\\u5207\\u63db\\u8996\\u89d2\\u67e5\\u770b\\u6b64\\u808c\\u8089\' : \'Switch view to see this muscle\');',
  '  } else {',
