  '    setTimeout(function(){ document.querySelectorAll(\'.mp.highlighted\').forEach(function(p){p.classList.remove(\'highlighted\');}); }, 2500);',
  '  }',
  '  // Show inline detail panel (not modal) in muscle map mode',
