  '  h += \'<button class=\' + dq + \'mi-tab\' + (initTab===\'massage\'?\' on\':\'\') + dq + \' data-mitp=\' + dq + \'massage\' + dq + \'>\' + (z ? \'\\u6309\\u6469\\u624b\\u6cd5 Massage\' : \'Massage \\u6309\\u6469\') + \'</button>\';',
  '  h += \'<button class=\' + dq + \'mi-tab\' + (initTab===\'contra\'?\' on\':\'\') + dq + \' data-mitp=\' + dq + \'contra\' + dq + \'>\' + (z ? \'\\u7981\\u5fcc\\u8b49 Contra\' : \'Contra \\u7981\\u5fcc\') + \'</button>\';',
  '  h += \'</div>\';',
