  '  h += \'<b>\' + (z?\'\\u8840\\u6db2\\u4f9b\\u61c9\':\'Artery\') + \':</b> \' + (z?db.arz:db.are) + \'</div>\';',
  '  h += \'<div class=\' + dq + \'mi-st\' + dq + \'>\' + (z?\'\\u89f8\\u767c\\u9ede TRIGGER POINTS\':\'TRIGGER POINTS \\u89f8\\u767c\\u9ede\') + \'</div>\';',
  '  db.tp.forEach(function(t){ h += \'<div class=\' + dq + \'mi-tp-item\' + dq + \'><span class=\' + dq + \'mi-tp-dot\' + dq + \'></span><span class=\' + dq + \'mi-tp-txt\' + dq + \'>\' + (z?t.z:t.e) + \'</span></div>\'; });',
  '  h += \'<div class=\' + dq + \'mi-st\' + dq + \'>\' + (z?\'\\u7b4b\\u819c\\u7dda FASCIAL CHAIN\':\'FASCIAL CHAIN \\u7b4b\\u819c\\u7dda\') + \'</div>\';',
