  '  if (mdb && mdb.techniques) {',
  '    // TP map',
  '    h += \'<div class=\' + dq + \'mi-st\' + dq + \'>\' + (z?\'\\u89f8\\u767c\\u9ede\\u4f4d\\u7f6e TRIGGER POINTS\':\'TRIGGER POINTS \\u89f8\\u767c\\u9ede\') + \'</div>\';',
  '    h += \'<div class=\' + dq + \'tp-map\' + dq + \'>\';',
  '    mdb.tp.forEach(function(t){',
  '      h += \'<div class=\' + dq + \'tp-badge\' + dq + \'><span class=\' + dq + \'tp-badge-dot\' + dq + \'></span><span class=\' + dq + \'tp-badge-txt\' + dq + \'>\' + (z?t.locZh:t.loc) + \'</span></div>\';',
  '    });',
  '    h += \'</div>\';',
  '    h += \'<div class=\' + dq + \'mi-st\' + dq + \' style=\' + dq + \'margin-top:10px\' + dq + \'>\' + (z?\'\\u624b\\u6cd5\\u8aaa\\u660e TECHNIQUES\':\'TECHNIQUES \\u624b\\u6cd5\') + \'</div>\';',
  '    mdb.techniques.forEach(function(t){',
  '      var pressureW = t.pressure + \'%\';',
  '      var pressureCol = t.pressure > 65 ? \'#ff2e52\' : t.pressure > 40 ? \'#ff6b2b\' : \'#00b4ff\';',
