  '      h += \'<span class=\' + dq + \'mc-tag mc-position\' + dq + \'>\\ud83d\\udccf \' + (z?t.position:t.position) + \'</span>\';',
  '      h += \'</div></div>\';',
  '    });',
  '  } else {',
  '    h += \'<div style=\' + dq + \'padding:16px;color:var(--muted);font-size:11px;text-align:center\' + dq + \'>\' + (z?\'\\u6309\\u6469\\u8cc7\\u6599\\u6e96\\u5099\\u4e2d...\':\'Massage data coming soon...\') + \'</div>\';',
  '  }',
  '  h += \'</div>\';',
  '',
  '  // ── CONTRA TAB ──',
  '  h += \'<div class=\' + dq + \'mi-tab-panel\' + (initTab===\'contra\'?\' on\':\'\') + dq + \' data-mitc=\' + dq + \'contra\' + dq + \'>\';',
  '  if (mdb && mdb.contra) {',
  '    mdb.contra.forEach(function(c){',
  '      h += \'<div class=\' + dq + \'contra-item\' + dq + \'>\';',
  '      h += \'<span class=\' + dq + \'contra-icon\' + dq + \'>\' + c.icon + \'</span>\';',
  '      h += \'<div class=\' + dq + \'contra-text\' + dq + \'><b>\' + (z?c.titleZh:c.title) + \'</b>\' + (z?c.descZh:c.desc) + \'</div>\';',
  '      h += \'</div>\';',
  '    });',
  '  } else {',
  '    h += \'<div style=\' + dq + \'padding:16px;color:var(--muted);font-size:11px;text-align:center\' + dq + \'>\' + (z?\'\\u8cc7\\u6599\\u6e96\\u5099\\u4e2d...\':\'Data coming soon...\') + \'</div>\';',
  '  }',
  '  h += \'</div>\';',
  '',
  '  panel.innerHTML = h;',
  '  panel.classList.add(\'show\');',
  '',
  '  // Tab switching',
  '  panel.querySelectorAll(\'.mi-tab\').forEach(function(btn){',
  '    btn.addEventListener(\'click\', function(){',
  '      var tp = this.dataset.mitp;',
  '      panel.querySelectorAll(\'.mi-tab\').forEach(function(b){ b.classList.remove(\'on\'); });',
  '      panel.querySelectorAll(\'.mi-tab-panel\').forEach(function(p){ p.classList.remove(\'on\'); });',
  '      this.classList.add(\'on\');',
  '      var tpanel = panel.querySelector(\'[data-mitc=\' + dq + tp + dq + \']\');',
  '      if (tpanel) tpanel.classList.add(\'on\');',
  '    });',
  '  });',
  '',
  '  setTimeout(function(){ panel.scrollIntoView({behavior:\'smooth\',block:\'nearest\'}); }, 100);',
  '}',
  '',
  'function doSearch(q) {',
  '  if (!q || !q.trim()) return [];',
  '  var lq = q.toLowerCase().trim();',
  '  return MIDX.filter(function(m) {',
  '    return m.en.toLowerCase().includes(lq) || m.zh.includes(lq) || m.slug.includes(lq);',
  '  });',
  '}',
  '',
  'function showSR(results) {',
  '  var el = document.getElementById(\'search-results\');',
  '  if (!results.length) {',
  '    el.innerHTML = \'<div class="no-results">\' + (zh() ? \'\\u627e\\u4e0d\\u5230\\u76f8\\u7b26\\u7684\\u808c\\u8089\' : \'No muscles found\') + \'</div>\';',
  '  } else {',
  '    el.innerHTML = results.map(function(m) {',
  '      return \'<div class="sr-item" data-slug="\' + m.slug + \'">\' +',
  '        \'<span class="sr-dot" style="background:\' + m.col + \';box-shadow:0 0 4px \' + m.col + \'"></span>\' +',
  '        \'<div><div class="sr-en">\' + m.en + \'</div><div class="sr-zh">\' + m.zh + \'</div></div>\' +',
  '        \'<span class="sr-layer">\' + m.layer.toUpperCase() + \'</span></div>\';',
  '    }).join(\'\');',
  '    el.querySelectorAll(\'.sr-item\').forEach(function(item) {',
  '      item.addEventListener(\'click\', function() {',
  '        clearSearch();',
  '        selMuscle(this.dataset.slug);',
  '      });',
  '    });',
  '  }',
  '  el.classList.add(\'show\');',
  '}',
  '',
  'function clearSearch() {',
  '  document.getElementById(\'search-results\').classList.remove(\'show\');',
  '  document.getElementById(\'search-input\').value = \'\';',
  '  document.getElementById(\'search-clear\').classList.remove(\'show\');',
  '}',
  '',
  'document.getElementById(\'search-input\').addEventListener(\'input\', function() {',
  '  var q = this.value;',
  '  document.getElementById(\'search-clear\').classList.toggle(\'show\', q.length > 0);',
  '  q.length >= 1 ? showSR(doSearch(q)) : document.getElementById(\'search-results\').classList.remove(\'show\');',
  '});',
  '',
  'document.getElementById(\'search-input\').addEventListener(\'keydown\', function(e) {',
  '  if (e.key === \'Escape\') clearSearch();',
  '  if (e.key === \'Enter\') {',
  '    var r = doSearch(this.value);',
  '    if (r.length === 1) { clearSearch(); selMuscle(r[0].slug); }',
  '  }',
  '});',
  '',
  'document.getElementById(\'search-clear\').addEventListener(\'click\', clearSearch);',
  '',
  'document.addEventListener(\'click\', function(e) {',
  '  if (!e.target.closest(\'.search-wrap\')) document.getElementById(\'search-results\').classList.remove(\'show\');',
  '});',
  '',
  'document.querySelectorAll(\'.rp-tab\').forEach(function(btn) {',
  '  btn.addEventListener(\'click\', function() {',
  '    var mode = this.dataset.rpt;',
  '    document.querySelectorAll(\'.rp-tab\').forEach(function(b){b.classList.remove(\'on\');});',
  '    this.classList.add(\'on\');',
  '    document.getElementById(\'ps-analysis\').style.display = mode===\'analysis\' ? \'\' : \'none\';',
  '    document.getElementById(\'ps-search\').style.display = mode===\'search\' ? \'\' : \'none\';',
  '    document.getElementById(\'ps-stretch\').style.display = mode===\'stretch\' ? \'\' : \'none\';',
  '    document.getElementById(\'search-bar\').style.display = mode===\'search\' ? \'flex\' : \'none\';',
  '    if (mode===\'search\') {',
  '      document.getElementById(\'main\').classList.add(\'map-mode\');',
  '      buildMI();',
  '      setTimeout(function(){document.getElementById(\'search-input\').focus();}, 100);',
  '    } else if (mode===\'stretch\') {',
  '      document.getElementById(\'main\').classList.remove(\'map-mode\');',
  '      document.getElementById(\'mi-detail\').classList.remove(\'show\');',
  '      buildStretch();',
  '    } else {',
  '      document.getElementById(\'main\').classList.remove(\'map-mode\');',
  '      document.getElementById(\'mi-detail\').classList.remove(\'show\');',
  '    }',
  '  });',
  '});',
