  '',
  'var SKEL_URL = "/skeleton.svg";',
  'var skelLoaded = false;',
  'function alignBoneImg() {',
  '  var bsvgEl = document.getElementById("bsvg");',
  '  var caEl = document.getElementById("ca");',
  '  var img = document.getElementById("bone-real-img");',
  '  if (!bsvgEl || !caEl || !img) return;',
  '  var br = bsvgEl.getBoundingClientRect();',
  '  var cr = caEl.getBoundingClientRect();',
  '  var lft = br.left - cr.left;',
  '  var tp = br.top - cr.top;',
  '  img.style.position = "absolute";',
  '  img.style.left = lft + "px";',
  '  img.style.top = tp + "px";',
  '  img.style.width = br.width + "px";',
  '  img.style.height = br.height + "px";',
  '  img.style.objectFit = "fill";',
  '  img.style.pointerEvents = "none";',
  '  img.style.opacity = "0.95";',
  '}',
  'function loadSkeleton(cb) {',
  '  if (skelLoaded) { alignBoneImg(); cb(); return; }',
  '  var img = document.getElementById("bone-real-img");',
  '  if (!img) return;',
  '  img.onload = function() { skelLoaded = true; alignBoneImg(); cb(); };',
  '  img.onerror = function(e) { console.error("skeleton load failed", e); };',
  '  if (!img.src || img.src.indexOf("skeleton.svg") < 0) img.src = SKEL_URL;',
  '  else if (img.complete) { skelLoaded = true; alignBoneImg(); cb(); }',
  '}',
