    'var BONE_HS = [',
  '  {key:"skull",    x:168,y:30, w:72, h:95},',
  '  {key:"cervical", x:183,y:100,w:39, h:52},',
  '  {key:"clavicle", x:125,y:143,w:170,h:25},',
