    '',
  'var bmBuilt = false;',
  'var bmBoneBuilt = false;',
  'var bmMode = "muscle";',
  'function buildBodyMap() {',
  '  if (!bmBuilt) {',
  '    bmBuilt = true;',
  '    var hb = document.getElementById(\'hb-svg\');',
  '    Object.keys(BM_SVG).forEach(function(part) {',
  '      var wrapper = document.createElement(\'div\');',
  '      wrapper.innerHTML = BM_SVG[part];',
  '      var svg = wrapper.firstChild;',
  '      svg.title = BM_LABELS[part] || part;',
  '      (function(p,s){ s.addEventListener(\'click\', function() { document.querySelectorAll(\'#hb-svg svg\').forEach(function(x){x.classList.remove(\'bm-active\');}); s.classList.add(\'bm-active\'); showBMRegion(p); }); })(part, svg);',
  '      hb.appendChild(svg);',
  '    });',
  '  }',
  '  if (!bmBoneBuilt) {',
  '    bmBoneBuilt = true;',
  '    var hbb = document.getElementById(\'hb-bone-svg\');',
  '    hbb.innerHTML = \'\\u8f09\\u5165\\u4e2d...\';',
  '    loadSkeleton(function() {',
  '      var viewer = document.querySelector(\'.bm-viewer\');',
  '      var vh = viewer ? viewer.offsetHeight : 480;',
  '      var vw = viewer ? viewer.offsetWidth : 240;',
  '      var imgH = Math.min(vh - 16, 560);',
  '      var imgW = Math.round(imgH * 435.7 / 841.9);',
  '      if (imgW > vw - 16) { imgW = vw - 16; imgH = Math.round(imgW * 841.9 / 435.7); }',
  '      hbb.style.cssText = \'position:relative;width:\' + imgW + \'px;height:\' + imgH + \'px;\';',
  '      var img = hbb.querySelector(\'img\');',
  '      if (img) { img.style.width = imgW + \'px\'; img.style.height = imgH + \'px\'; }',
  '      var oSvg = document.createElementNS(\'http://www.w3.org/2000/svg\',\'svg\');',
  '      oSvg.setAttribute(\'viewBox\',\'0 0 435.7 841.9\');',
  '      oSvg.setAttribute(\'preserveAspectRatio\',\'xMidYMid meet\');',
  '      oSvg.style.cssText = \'position:absolute;top:0;left:0;width:\' + imgW + \'px;height:\' + imgH + \'px;\';',
  '      BONE_HS.forEach(function(hs) {',
  '        var rect = document.createElementNS(\'http://www.w3.org/2000/svg\',\'rect\');',
  '        rect.setAttribute(\'x\', hs.x); rect.setAttribute(\'y\', hs.y);',
  '        rect.setAttribute(\'width\', hs.w); rect.setAttribute(\'height\', hs.h);',
  '        rect.setAttribute(\'rx\',\'4\');',
  '        rect.style.cssText = \'fill:transparent;stroke:rgba(122,184,212,0.25);stroke-width:1;cursor:pointer;transition:fill 0.15s;\';',
  '        rect.addEventListener(\'mouseenter\',function(){ this.style.fill=\'rgba(122,184,212,0.2)\';this.style.stroke=\'rgba(122,184,212,0.8)\'; });',
  '        rect.addEventListener(\'mouseleave\',function(){ if(!this.classList.contains(\'bhs-on\')){this.style.fill=\'transparent\';this.style.stroke=\'rgba(122,184,212,0.25)\';} });',
  '        (function(h,r){ r.addEventListener(\'click\',function(){',
  '          oSvg.querySelectorAll(\'rect\').forEach(function(x){x.classList.remove(\'bhs-on\');x.style.fill=\'transparent\';x.style.stroke=\'rgba(122,184,212,0.25)\';});',
  '          r.classList.add(\'bhs-on\');r.style.fill=\'rgba(157,208,232,0.28)\';r.style.stroke=\'rgba(157,208,232,0.9)\';',
  '          showBMBone(h.key);',
  '        }); })(hs,rect);',
  '        oSvg.appendChild(rect);',
  '      });',
  '      hbb.appendChild(oSvg);',
  '    });',
  '  }',
  '  document.querySelectorAll(\'.bm-mode-btn\').forEach(function(btn) {',
  '    btn.addEventListener(\'click\', function() {',
  '      if (this.dataset.bm === bmMode) return;',
  '      bmMode = this.dataset.bm;',
  '      document.querySelectorAll(\'.bm-mode-btn\').forEach(function(b){b.classList.remove(\'on\');});',
  '      this.classList.add(\'on\');',
  '      document.getElementById(\'hb-svg\').style.display = bmMode===\'muscle\' ? \'\' : \'none\';',
  '      document.getElementById(\'hb-bone-svg\').style.display = bmMode===\'bone\' ? \'\' : \'none\';',
  '      document.getElementById(\'bm-muscles\').innerHTML = \'<div class="bm-hint">\' + (bmMode===\'bone\' ? \'\\u9ede\\u64ca\\u9aa8\\u9abc\\u67e5\\u770b\\u9644\\u8457\\u808c\\u8089\' : \'\\u9ede\\u64ca\\u8eab\\u9ad4\\u5340\\u57df\\u67e5\\u770b\\u808c\\u8089\') + \'</div>\';',
  '    });',
  '  });',
  '}',
  '',
  'function showBMRegion(part) {',
  '  var slugs = BODYMAP_DB[part] || [];',
  '  var el = document.getElementById(\'bm-muscles\');',
  '  var label = BM_LABELS[part] || part;',
  '  var html = \'<div class="bm-region-title">\' + label + \'</div>\';',
  '  slugs.forEach(function(slug) {',
  '    var info = ANATOMY_DB[slug];',
  '    if (!info) return;',
  '    html += \'<button class="bm-muscle-btn" data-slug="\' + slug + \'"><span class="bm-mn">\' + info.le + \'</span><span class="bm-mz">\' + info.zh + \'</span></button>\';',
  '  });',
  '  el.innerHTML = html;',
  '  el.querySelectorAll(\'.bm-muscle-btn\').forEach(function(btn) {',
  '    btn.addEventListener(\'click\', function() {',
  '      var slug = this.dataset.slug;',
  '      document.querySelector(\'.rp-tab[data-rpt="search"]\').click();',
  '      selMuscle(slug);',
  '    });',
  '  });',
  '}',
  '',
  'function showBMBone(bone) {',
  '  var data = BONE_MUSCLE_DB[bone];',
  '  if (!data) return;',
  '  var el = document.getElementById(\'bm-muscles\');',
  '  var html = \'<div class="bm-region-title">\' + data.label + \'</div>\';',
  '  html += \'<div class="bm-bone-label">\' + data.labelZh + \'</div>\';',
  '  data.slugs.forEach(function(slug) {',
  '    var info = ANATOMY_DB[slug];',
  '    if (!info) return;',
  '    html += \'<button class="bm-muscle-btn" data-slug="\' + slug + \'"><span class="bm-mn">\' + info.le + \'</span><span class="bm-mz">\' + info.zh + \'</span></button>\';',
