  'var stretchBuilt = false;',
  'function buildStretch() {',
  '  var slugs = Object.keys(STRETCH_DB);',
  '  var sel = document.getElementById(\'stretch-select\');',
  '  if (!stretchBuilt) {',
  '    stretchBuilt = true;',
  '    var html = \'\';',
  '    slugs.forEach(function(slug) {',
  '      var d = STRETCH_DB[slug];',
  '      html += \'<button class="stretch-sel-btn" data-slug="\' + slug + \'">\' + d.le + \'</button>\';',
  '    });',
  '    sel.innerHTML = html;',
  '    sel.querySelectorAll(\'.stretch-sel-btn\').forEach(function(btn) {',
  '      btn.addEventListener(\'click\', function() {',
  '        sel.querySelectorAll(\'.stretch-sel-btn\').forEach(function(b){b.classList.remove(\'on\');});',
  '        this.classList.add(\'on\');',
  '        showStretch(this.dataset.slug);',
  '      });',
  '    });',
  '    var first = sel.querySelector(\'.stretch-sel-btn\');',
  '    if (first) { first.classList.add(\'on\'); showStretch(slugs[0]); }',
  '  }',
  '}',
  '',
  'function showStretch(slug) {',
  '  var d = STRETCH_DB[slug];',
  '  if (!d) return;',
  '  var html = \'\';',
  '  d.stretches.forEach(function(s) {',
  '    var steps = s.steps.map(function(st){return \'<li>\' + st + \'</li>\';}).join(\'\');',
  '    html += \'<div class="stretch-card"><div class="stretch-card-title">\' + s.name + \'</div><div class="stretch-card-zh">\' + s.nameZh + \'</div><ol class="stretch-card-steps">\' + steps + \'</ol><div class="stretch-meta"><span class="stretch-tag">\' + s.duration + \'</span><span class="stretch-tag">\' + s.type + \'</span></div></div>\';',
  '  });',
  '  document.getElementById(\'stretch-cards\').innerHTML = html;',
  '}',
